<script lang="ts">
	import Icon, { type IconName } from '$lib/components/ui/Icon.svelte';
	let query = $state('');
	const sections = [
		{ id:'version', title:'Version and implementation status', summary:'What this build contains and what comes next.', body:['This documentation describes RivetPanel 0.5.0. The root VERSION file is authoritative and the changelog records every notable release and in-progress change.','0.5.0 adds Minecraft and Steam game servers and remote execution through rivet-agent. Agent nodes enroll with one-use credentials, connect outward with panel-issued certificates and can run explicitly placed bots and game servers.','The remaining staged work is tracked in docs/implementation-status.md in the source distribution. The control plane still owns the Docker socket in local-runner mode; stored settings and agent capability reports must not be treated as independent attestation or network, filesystem or kernel enforcement.'] },
		{ id:'quickstart', title:'Quick start', summary:'Create, configure and run your first bot.', body:['Open Templates for a tested starting point: bot templates, every game server type you may create, and site templates with a preview. Or create a blank bot and upload your project in Files.','Add secrets such as DISCORD_TOKEN in Environment. Secrets are encrypted at rest and never returned after saving.','Review runtime, memory and restart policy, then start the bot. Follow build output and live logs from its page.'] },
		{ id:'remote-nodes', title:'Remote nodes', summary:'Enroll a host and place bots or game servers on it.', body:['Enable the agents preview module, expose the raw TLS agent listener and open Administration → Nodes. Add a remote node, then run the one-time rivet-agent enroll command on that host and start its systemd service. The agent connects outward, so it needs no inbound management port.','Administrators choose a node while creating an empty bot, a bot from a template or from GitHub (both need the node to be connected) or a game server; other users\' servers stay on the panel\'s own node. Drain blocks new placement while existing servers keep running; disabling or revoking the certificate disconnects the agent. Desired state remains in the panel and resynchronizes after reconnect.','Lifecycle, console, Files, live container statistics, Minecraft status, backups and GitHub deployments work remotely. Backup archives are stored by the panel; restore is journaled on the node until the panel confirms its database update. For GitHub deployments the panel downloads the repository (at most 1 GiB) and streams it to the node, which checks and stages all of it before swapping and keeps the previous files until the panel records the commit; deploys to an offline node are refused and polling waits for it to reconnect. GitHub publish and push read the files the node selects (same exclusions and limits) over the same connection and are refused while the node is offline. The package manager and the AI assistant\'s file tools edit the node\'s files directly: package edits and AI changes are checked against the revision that was read, so a concurrent change is refused instead of overwritten, and AI changes stay reversible on the node until the panel records them; both are refused while the node is offline. A template bot on a remote node gets its files on that node in one transaction that is committed only after the bot is recorded; if creation fails the bot is removed again through its agent. Modrinth plugins and mods for a remote game server are downloaded by the panel to a temporary file, checked against the CDN allowlist, the 256 MiB limit and the published SHA-512, and only then sent to the node; the temporary file is deleted straight away. Both are refused while the node is offline. SFTP folders of remote servers are served through the agent (uploads reach the node when the file is closed; listings show no modification times), and the Databases tab reads remote database states and logs from the node; both are refused while the node is offline. The AI assistant\'s diagnostics run on the node in the same offline, resource-limited container (at most two at once per node). Add-ons chosen when creating a server on a node are checked for that node first; their data lives on the node and is deleted there when an add-on is removed or attached again. The node reports CPU, memory and disk: the live stats strip shows the node\'s free disk, and the panel refuses to stage a restore, deployment, change or file of 1 MiB or more when it would leave less than 256 MiB free. A GitHub push that arrives while the node is offline waits and deploys the newest commit once the agent reconnects, unless the repository link changed meanwhile. Before a game server on a node gets an automatic port, the node checks that the port can be bound and busy ports are skipped; starting a stopped server whose port has been taken is refused with the port named. This is a check, not a reservation, so a start can still fail if something takes the port in between. Panel and agent must run the same protocol version (8), so upgrade them together. Node capability and telemetry reports are informational; Docker enforces container limits on the node.'] },
		{ id:'game-servers', title:'Game servers', summary:'Minecraft and Steam server types, egg import, installation, ports and player status.', body:['Game servers → New server (or New → Minecraft server or Steam game server in the top bar) offers Paper, Purpur, Vanilla, Fabric, Forge, NeoForge, Folia, the Velocity proxy and the Steam types below. It walks through four steps: pick the game (searchable, grouped, with game icons), choose the version and the game\'s own settings, set the name, memory and CPU (and the workspace or node when there is a choice; the largest memory and CPU offered are the chosen node\'s own, and changing the node resizes the server to fit it), then review, accept the licence terms the game requires (such as the Minecraft EULA) and create. A game server has the same console, files, SFTP, backups, schedules and sharing as a bot.','The first start installs the server: the panel downloads the server software from the official source and checks its published checksum, then picks the lowest Java version that runs it: the highest of the provider’s declared minimum (Velocity 4 needs Java 25), the Minecraft release’s requirement (Java 17 for 1.20.1, Java 25 for 26.x) and the class files of the downloaded jar. A Java image that is too old for the downloaded version is replaced at installation; a server that crashed with UnsupportedClassVersionError starts after Reinstall. Forge and NeoForge also run their installer in a container. While this happens the server shows Installing and the output is kept as an operation.','Startup lists the server type, the startup command and the settings. Changing the version reinstalls the server software on the next start; worlds, plugins, mods and settings stay. Reinstall does the same on demand, and the Java image can be chosen by hand when a mod needs a specific Java.','JVM arguments (Java types, under Startup) adds options to java right after the heap size. Presets fill the box: Aikar\'s flags (G1 tuning for Minecraft, with the larger-heap values above 12 GB), ZGC (Java 21+, large heaps) and None; the page shows the server\'s Java version and warns when a preset needs a newer one. Only JVM option shapes (-XX:…, -X…, -D…, --add-opens=…, --add-modules=…, -javaagent: with a jar in the server\'s files) and the characters letters, digits and . _ : + = , / @ % - are accepted, at most 2 KiB. -Xmx and -Xms are refused because the heap follows the memory limit, and so are -jar, -cp and native agents. Changes can be made while the server runs and apply at the next start (Restart to apply). Servers created before this feature get it with Update on their Startup page.','Manage shows a Connect block with the address players type into the game, a copy button and where to paste it. The host is the allocation alias or bound IP, otherwise the node\'s Public address from Administration → Nodes (the local node has one too), otherwise the node\'s own IP when the panel knows it. The panel\'s own host name is never given to players and cannot be set as a public address; for a name, point a DNS-only (not proxied) record at the node and enter it there. Without an address the block shows the port and asks an administrator to set one; localhost and private addresses are marked as reachable only from this machine or your network. The port is left out when it is the game\'s default (25565 for Minecraft); copying always includes it.','Network shows the server\'s ports. The primary port is what players connect to; extra ports are for plugins such as voice chat or web maps. New servers take a free port from the pool administrators manage under Administration → Allocations, or the next free port from 25565. Forward the primary port (TCP and UDP) on your router to reach the server from the internet.','Players lists who is online, operators, the whitelist and bans, with buttons for op, kick, ban and whitelist changes. Properties edits the common server.properties settings and keeps the rest of the file. Plugins (Paper, Purpur, Folia, Velocity) or Mods (Fabric, Forge, NeoForge) search Modrinth for projects that fit the server and install them with checksum verification; restart to load them.','Schedules can run a task chain: console commands, power actions and backups in order with waits in between, such as a warned restart that announces itself in chat and saves the world first.','Stop sends the server\'s own stop command and waits for the world to save before falling back to a normal container stop. The console sends commands to the server without a leading slash. While running, the panel shows players, the version and the message of the day.','Steam types (Valheim, Rust, Project Zomboid) are downloaded with an anonymous SteamCMD login in a separate install container on the first start and on Reinstall; no Steam account is ever needed or stored. The Steam beta branch setting picks a branch (plain names only). Downloads have a time limit and a size watchdog that stops SteamCMD when the files grow too large (a watchdog, not a disk quota). Valheim needs a server password of at least 5 characters; its game and query ports are allocated as a consecutive pair. Steam servers stop with the game\'s own signal or console command, and while they run on this host the panel shows players, name, map and version from the Steam query. Running these games is subject to Steam\'s and each game\'s terms.','Administrators can convert a Pterodactyl egg (PTDL_v1 or PTDL_v2 JSON, at most 512 KiB) under Administration → Server types → Import Pterodactyl egg. The draft YAML and a list of warnings (config parsers, rules, features and placeholders that could not be mapped) are shown for review and editing; nothing is saved or downloaded until Save. Imported install scripts run like every install script: in the install container as the unprivileged server user, not as root.','Limits: disk space, bandwidth and outbound traffic are not limited by RivetPanel; Steam status queries work only on this host; game servers run on this host or on an enrolled remote node.'] },
		{ id:'deploy', title:'Deployment and GitHub', summary:'Manual uploads, repositories, automatic deploys and pushing back.', body:['Manual projects can be edited in the browser or over SFTP. GitHub projects download a repository archive without installing git on the host.','Any public repository works without a GitHub connection: in New bot → Deploy from GitHub, paste owner/name or a GitHub link (a /tree/branch/folder link fills those in). Connect GitHub under Settings for private repositories, your repository list, publishing and a higher rate limit.','Analyze repository works out the language, start and build commands, variables, databases and resources. Well-known bots (Red-DiscordBot, YAGPDB) use verified recipes; others are detected from their files and can be refined by the AI when an administrator configured a provider. Suggestions only prefill the form; review a suggested build command before creating the bot.','Automatic deploys use a signed webhook when your GitHub account administers the repository and the panel has a public address; otherwise the branch is checked every five minutes. New GitHub bots can start automatically after their first deployment.','A failed build keeps the previous generation available. Use operation history for the exact stage and output.'] },
		{ id:'addons', title:'Databases', summary:'PostgreSQL, Redis, MongoDB and MariaDB next to a bot.', body:['Add databases while creating a bot or on its Databases tab (bot stopped). Each runs in its own capped container on a private network without internet access that only this bot can reach, by host name: postgres, redis, mongodb or mariadb.','The bot receives connection variables such as DATABASE_URL, POSTGRES_PASSWORD, REDIS_URL, MONGODB_URI and MYSQL_URL automatically. Reference them from your own variables as ${NAME}, for example YAGPDB_PQPASSWORD=${POSTGRES_PASSWORD}. Show connection reveals them.','Add-ons start before the bot (it waits for their health checks), stop with it and keep their data between starts. Data lives outside the bot files and is deleted when the add-on or the bot is removed. Add-on memory counts toward your limits. Add-on data is not part of backups: dump it from the bot if you need copies.'] },
		{ id:'build', title:'Build commands and logos', summary:'Custom build steps for larger projects, and bot and site logos.', body:['Startup → Build command replaces the language\'s default build, for example cd cmd/mybot && go build -o /workspace/app . It runs with sh before every start in the build container, with internet access but without the bot\'s variables, and stops at the first failing line.','Bot Settings → Logo uploads a custom logo (PNG, JPEG, WebP or GIF, cropped to a square). Without one the Discord avatar is shown; Get avatar from Discord fetches it with the bot token stored in the bot\'s variables. A site uses its custom logo, else its own favicon, else its bot\'s logo.'] },
		{ id:'publish', title:'Publishing a bot to GitHub', summary:'Create a repository from a bot and push later changes.', body:['Deploy → Publish to GitHub creates a repository under your account or organization (private by default), pushes the bot’s files as the first commit and links the bot to it, optionally with auto-deploy. For a linked bot, Push to GitHub commits the current files to the linked branch.','Pushing uses your own GitHub connection with repository access and never force-pushes: if the branch moved on GitHub, the push stops and you deploy those changes first. With a linked folder, only that folder is replaced.','.gitignore files (root and nested) are honored. Dependencies, .git, panel metadata and .env files are always left out (.env.example is kept) and panel environment variables are never pushed. The dialog lists every file before anything is created. Limits: 5,000 files, 200 MiB, 25 MiB per file. For a bot on a remote node the node selects and serves the files; nothing is copied to the panel.'] },
		{ id:'workspaces', title:'Workspaces and roles', summary:'Group bots and sites for a team.', body:['Every account has a Personal workspace; create team workspaces under Settings → Workspaces and add people by the email they sign in with. The sidebar switcher scopes the overview, Sites and new bots to one workspace.','Owner and Admin act as the owner of every bot and site in the workspace. Developer creates, deploys and operates bots and sites, edits files and environment variables, but cannot change resources, delete or share. Viewer only reads status and console output.','Per-bot sharing still adds access on top. Transferring a bot moves it into the new owner’s personal workspace. Administrators see every workspace, account, bot and recent deployment under Administration.'] },
		{ id:'roles', title:'Account roles and email verification', summary:'Custom roles, delegated administration and verified addresses.', body:['Every account holds a role: the built-in Administrator (every permission) or User (everything for their own bots, servers and sites, no administration), or a custom role made under Administration → Roles from named permissions such as bots.create, bots.files, nodes.manage or users.manage. Assign roles on the Users page; a change applies on the account’s next request.','The server refuses (403) anything the role does not include, for owners too. Console, power, files and environment permissions also limit workspace roles and per-bot sharing, so a full-access share cannot give back what the role removes. A custom role can delegate parts of the administration, but a delegate never grants more than it holds or changes an account holding administration permissions it lacks, and only administrators make administrators or open the environment editor and modules. Role changes are recorded in the activity log.','New accounts confirm their email address with a one-use link from Settings → Profile (24 hours; GitHub and Discord sign-ups count as verified). Changing your address needs your password and takes effect only when the new address is confirmed. Administration → Panel settings can withhold chosen permissions from unverified accounts; without email, account managers mark addresses verified (or change them) on the Users page.'] },
		{ id:'sign-in', title:'Single sign-on, passkeys and API clients', summary:'OpenID Connect providers, passkeys and scoped API credentials.', body:['Administration → Single sign-on adds OpenID Connect providers (Keycloak, Authentik, Okta, Entra ID, Google). Set the panel address first and register the redirect URI shown in the form; the issuer must use https (http only on this machine) and its discovery document is checked when you save. The client secret is stored encrypted. Sign-in uses PKCE, state and nonce, and the panel verifies the identity token’s signature, issuer, audience and expiry.','A provider identity already linked signs in its account. Otherwise it links to the account with the same address only when the provider says the address is verified, the option is on and the account holds no administration permission; otherwise people sign in another way and connect the provider under Settings → Connected accounts. New people get an account only when sign-up is on, with the chosen role (never Administrator). Two-step sign-in still asks for the code.','Settings → Security → Passkeys adds passkeys (needs your password). Sign in with a passkey needs no password and no code; with two-step sign-in on, a passkey can replace the code. Passkeys need the panel address to be a host name and stop working if it changes.','Settings → SFTP and API keys → API clients creates rvc_ bearer tokens for the whole API with only the permissions you choose (never more than your role, re-checked on every request), optionally limited to some bots and workspaces (403 elsewhere). Clients never act as administrators and cannot manage passwords, sessions or keys. Administration → API clients lists and revokes them. See docs/auth.md.'] },
		{ id:'sites', title:'Bot Sites and public pages', summary:'A public home attached directly to each Discord bot.', body:['Open a bot’s Public page tab to create its one integrated site. Page Studio publishes a generated page with its own headline, introduction, theme, accent, custom HTML, custom CSS and an isolated live preview. Private telemetry remains under Private insights.','Switch the same address to Custom files for a complete HTML, CSS and JavaScript site. Site files is a private working draft: saving never changes production. Publish draft creates an immutable release, and older releases remain available for instant rollback.','Generated pages can expose validated declarative widgets only after a developer enables Publish bot widgets. Raw stats, command usage, events, logs, secrets, owner identity and deployment details are never part of the public page response.','Add a custom domain, create the TXT ownership record plus the shown CNAME or address record, then check DNS. The domain is served only after verification.','A site’s address is its name followed by a sites domain, such as docs.sites.example.com. Change it in the site’s Settings: the move is immediate, the old address stops working and any site may take it, while verified custom domains keep working. A name is unique on each sites domain. Administrators add further sites domains under Administration → Sites and domains; each serves only after its _rivetpanel-domain TXT record is verified, and the reverse proxy still has to route it and hold a certificate for it.','Standalone sites can start from a template: Templates → Sites shows the five built-in starters (Landing page, Docs and blog, Portfolio, Coming soon and Game server community) with a framed preview that runs no scripts, and Create site asks for the name and address like Sites → New site, whose Start from field offers the same templates. The template’s files, with the site name filled in, become the first release, so the site is live at once; edit them in the draft editor or replace them with an upload. Creating from a template needs the sites.create permission and counts against the site size limit. The Game server community template shows this panel’s live status only when the status page is enabled and the panel is reachable over HTTPS; otherwise it links to it. Administrators cannot add their own site templates yet.'] },
		{ id:'appearance', title:'Appearance', summary:'Theme, accent color and corners.', body:['Settings → Appearance chooses light, dark or system theme, one of twelve accent colors, and a corner style: Square (no rounding anywhere), Subtle, Default or Rounded. These preferences apply to the current browser.'] },
		{ id:'ai', title:'AI assistant', summary:'One private chat for the whole panel that knows where you are.', body:['Open it with the Ask AI (sparkle) button in the top bar of any page, or with Ctrl+.. It is one chat, not one per bot: each message carries the bot or site, section and open file you were looking at, shown as a chip above the message box that you can dismiss for a single question. Ask in plain language, for example why a bot is not starting.','It reads a bot’s status, recent console output, build and deployment logs, permitted files and variable names, and can search the web for documentation. An administrator adds an OpenAI-compatible provider (DeepSeek is the preset) in the optional AI operator step of /setup or later under Administration → Panel settings, where providers can be edited, re-keyed, enabled, disabled, deleted and tested, and models discovered. Keys are encrypted and never shown again. Hosting works without any provider.','Ask first, the default, stops on a card before a diagnostic, a file change, a restart or secure environment input. Auto repair, available while a bot or site is open, first shows its envelope (the target, the tools it covers and the run limits) and needs one approval; secure input still waits for you. There are no tools for the startup command, deployments, site publication, GitHub pushes or kill. Diagnostics run one allowed command, such as a syntax check, the tests or the bot’s entry file, in a throwaway offline copy of the files; a command that is not allowed returns the list of those that are.','Each run is limited in both modes: 12 rounds, 20 minutes, 5 diagnostics, 3 apply attempts, 2 restarts, 32 changed files, 8 MiB of changed text and 2 MiB of retained tool output. A call over a limit is refused. Every model-initiated file change, diagnostic, restart and secure input is recorded in the activity log.','Chats are private to you, kept for 90 days and listed under the history button; reloading restores the active run, pending approvals, secure-input cards, change sets and Undo. Web research may use a private self-hosted SearxNG origin, while fetched pages must be public; addresses are checked at connect time.'] },
		{ id:'widgets', title:'Dashboard and public widgets', summary:'One validated schema for private operations and opt-in public pages.', body:['Send widgets in POST /api/v1/bot-telemetry or its WebSocket. Up to 48 widgets may be changed in one push and up to 240 active widgets are returned. Keys are upserted.','Kinds: metric, status, progress, text, chart, table, link, line, area, donut, gauge, heatmap, sparkline, kv, markdown, image, log and code. Bot content stays declarative inside the operator panel.','Optional fields: group (tab name, 48 chars), span (1, 2 or 3 columns), min_height (0–800 px), position (0–1000), and ttl_seconds (30–604800). A widget older than five minutes is marked stale.','On a public Bot Site, custom CSS can target [data-widget="widget-key"] or a renderer class such as .kind-metric. Turn off Publish bot widgets to remove every widget from the public page immediately.'] },
		{ id:'widget-data', title:'Widget data shapes', summary:'Payload conventions for every renderer.', body:['metric: {value, unit?, detail?, delta?}; status: {state: good|warn|bad|neutral, text}; progress/gauge: {value, max?, label?, unit?}.','chart/line/area/sparkline: {points:[{label,value}], unit?}; donut: {values:[{label,value}]}; heatmap: {cells:[{label,value}]}.','table: {columns:[string|{label}], rows:[[string|number|{label,url}]]}; kv: {items:[{key,value}]}; text/markdown/log: {text}; code: {code, language?}; image/link: {url, alt?/label?}.'] },
		{ id:'telemetry', title:'Telemetry limits', summary:'Rates, validation and retention.', body:['The request body is at most 64 KiB. Each bot may push 60 times per minute. A named stat is stored at most once every 10 seconds.','Per push: 16 stats, 20 commands, 10 events, 48 widget updates and 48 unpublish keys. Widget data is valid non-null JSON up to 4096 bytes. Validation errors identify the offending field.','Retention is configured by the administrator from one hour to 365 days; the default is seven days. A bot also has a bounded telemetry row history.'] },
		{ id:'health', title:'Health and alerts', summary:'Heartbeats and active probes for bots, server health, and notifications.', body:['A bot has three separate health signals. Process state (in the bot header) only says whether the container runs. The heartbeat says whether the bot’s own code is alive. The probe says whether the host can reach it. Heartbeat and probe are on the bot’s Health tab.','Heartbeat: every accepted telemetry push from the RivetPanel SDK is a heartbeat. Send the optional ready boolean as true once your client has logged in to Discord and false when it disconnects. The SDK snippet and the key it needs are on the bot’s Page tab. A bot that never reported is unknown, never failed, and never alerts.','Probe: a TCP probe passes when a published TCP port accepts a connection; an HTTP probe sends GET to a path and passes on a 200–399 reply without following redirects. Both connect through 127.0.0.1 to a port published in Network, so they cannot reach other hosts. Check every sets the interval, Timeout marks a slow check as failed, Failures before unhealthy and Successes before healthy set how many checks in a row change the state, and Startup grace ignores failures right after a start.','Restart when unhealthy replaces a stuck container once on the transition to unhealthy, not on every failed check, so a broken deployment cannot restart in a loop. Restart policy under Startup separately retries processes that exit with bounded exponential backoff. The “crashes in a row” count clears once a run has lasted a minute, on Start/Restart, and never includes install, build or start retries.','Game servers have no Health tab, SDK heartbeat or probe: their health is the process state plus the game query (players, latency and version in the header). The API refuses a probe for a game server and ignores a heartbeat rule.','Notifications are under Settings → Notifications of each bot and game server. They go to the owner’s account: the bell, email when Alert emails are on, and the Discord channel the owner connected under Settings → Connected accounts → Discord (not through a Discord bot). Bots choose crashes (at most one per bot per 10 minutes), deployments, backup failures, recoveries and an alert when a running bot stops reporting heartbeats for 1 minute to 1 hour; game servers choose crashes (including failed installs and starts) and backup failures. Send a test checks the Discord connection.','A host port that another container already publishes (another panel, any other tool) is not a crash: the start is refused with “Port N is already used by another container” (administrators also see the container’s name), nothing is retried or alerted, and a game server offers Pick a free port. New servers and administrators’ pool ports skip ports any container publishes.','Use the diagnostics page for database, container runtime, storage and runner checks.'] },
		{ id:'usage', title:'Usage analytics', summary:'Resource use, uptime, crashes, deployments and backups over time.', body:['Every bot and game server has an Analytics tab (anyone with console access to it): CPU and memory (averages with dashed peaks), network traffic, uptime, crashes and starts, workspace size, deployments (succeeded, failed, average duration) and backups (succeeded, failed, size) over 1 hour, 24 hours, 7, 30 or 90 days, with a CSV export of the rows shown.','The panel samples every bot once a minute (Docker stats locally, the agent for connected remote nodes; at most 100 running bots per pass, in rotation) and writes one row per bot per five minutes. Five-minute rows are kept 3 days, hourly rollups 35 days and daily rollups 400 days. Uptime counts only time a bot was meant to run; crashes come from the restart policy’s crash counter; deployments and backups are counted from the operations history, so they outlive its pruning. Workspace size is measured every 30 minutes for this panel’s own node only. A panel that was not running records nothing for that time.','Administration → Analytics (permission analytics.view) sums the same data across the panel: accounts, bots and servers by kind, CPU, memory and network in use, uptime, crashes, deployments, backups and top consumers, plus nodes and locations with nodes.manage and ticket volume and first-reply time with ticket access. Delegated viewers see only accounts they could manage and those accounts’ bots; API clients never count as administrators and clients limited to bots or workspaces cannot open the overview.'] },
		{ id:'support', title:'Notifications and support', summary:'The bell, notification preferences, support tickets, the help center and the status page.', body:['The bell in the top bar shows unread notifications: bot and server crashes and heartbeat alerts, deployments, failed backups, sharing, transfers, workspace membership and accepted invitations, announcements and support replies; accounts that manage nodes also hear when a node has been offline for 2 minutes and when it is back. All notifications lists, marks read and deletes them. The count refreshes every 30 seconds while the tab is visible. Each account keeps at most 200 notifications for 90 days, and only you see yours; API clients cannot read them.','Settings → Notifications turns each category on or off in the panel and by email. Email goes only to a verified address; alerts, deployments, backups and node notices also need Alert emails on your profile, and security notices are always emailed.','Support in the sidebar opens tickets with a subject, category, priority, an optional bot or server you can access and a message. Only you and the support team see your tickets (workspace members do not). Statuses are open, pending (waiting for you), resolved and closed; replying reopens a pending or resolved ticket, and you can close your own. Replies arrive under the bell and by email.','Staff need tickets.view_all (read everything, including internal notes) or tickets.manage (answer, internal notes, status, priority, assignment). Administrators hold both; custom roles can delegate them, but a delegated staff account never sees tickets of accounts with more administration permissions than it holds. Internal notes and assignments are never shown to the requester. Limits: 10 open tickets per account, 10 new tickets an hour, 10,000 characters per message, no attachments.','The Help center (/help) shows Markdown articles written under Administration → Knowledgebase (kb.manage). Drafts are visible to knowledgebase managers only; published articles are visible to everyone, to signed-in accounts or to support staff only. Visitors without an account can read public articles only while the public help center is turned on. HTML in an article is shown as text and never runs; links must be https://, http:// or a panel path. While you type a ticket subject, related articles are suggested.','The public status page (/status, managed under Administration → Status page with status.manage) shows only the components you add, under the names you choose: the panel, nodes and bots or game servers, with automatic states, incidents with an update timeline, scheduled maintenance and 90 daily uptime bars sampled every 5 minutes. It never shows internal ids, names, owners, addresses or errors, answers not found while disabled and is rate-limited per address. Days without samples show as no data.'] },
		{ id:'email', title:'Email (Mailgun)', summary:'Password reset, invitations, alert emails and security notices.', body:['Email is off until an administrator opens Administration → Panel settings → Email (Mailgun) and enters a Mailgun API key, a verified sending domain, its region (US or EU) and a sender such as RivetPanel <noreply@mg.example.com>. Press Send test to check the key, region and the domain\'s DNS records and to send one message. The key is stored encrypted and never shown again. The same values can be set with RIVET_MAILGUN_API_KEY, RIVET_MAILGUN_DOMAIN, RIVET_MAILGUN_REGION and RIVET_MAIL_FROM, in which case the environment wins.','With email and the panel address set, the sign-in page offers Forgot your password. The reset link works once, expires after an hour, and signs the account out everywhere when used; the request answers the same way whether or not the address has an account. Administrators can tick Email the link when inviting a user. Bot owners also get crash, deploy, backup and health alerts by email (Settings → Profile → Email turns this off), and every password or two-step change sends a security notice that cannot be turned off.','Administration → Announcements lets an administrator email HTML news or policy updates to every enabled account or to administrators only. Write the message, check the preview, send yourself a test (required before sending), then send. A notice goes to everyone in the audience; news skips accounts that turned news off in their profile. Send by also offers the notification inbox (plain text), which works without Mailgun. Each person sees only their own address, scripts and forms are stripped, and there is no draft, history or scheduling.','A Mailgun sandbox domain only delivers to recipients you authorize in Mailgun. RivetPanel does not receive Mailgun webhooks, so bounces and complaints are not tracked and nothing is retried. Email adds no background work: idle memory does not change.'] },
		{ id:'security', title:'Security and isolation', summary:'Current boundaries and production guidance.', body:['Bots run with resource limits, dropped capabilities and a read-only runtime where supported. Do not mount the Docker socket into bot containers. The panel host itself must be treated as privileged while it owns that socket.','Disable networking for bots that do not need it. Bandwidth intent is recorded but requires host traffic shaping for kernel enforcement. Put the panel behind TLS and keep encryption keys outside backups.','Use a dedicated host for untrusted tenants. Stronger isolation, egress allowlists, disk quotas, malware scanning and signed runtime verification are tracked platform hardening work.'] },
		{ id:'backups', title:'Backups and restore', summary:'Workspace, environment and restore safety.', body:['Manual and scheduled backups are checksummed. Environment inclusion is explicit because it contains encrypted secrets.','A restore creates a safety backup first and records verification details. Keep off-host copies; a backup on the same disk is not disaster recovery.'] },
		{ id:'automation', title:'Automation API', summary:'Tokens, idempotency and config-as-code foundations.', body:['Create scoped automation tokens under SFTP and API keys (for the whole API, use an API client; see Single sign-on, passkeys and API clients). Send an Idempotency-Key on mutating requests so CI retries do not duplicate work.','The machine-readable specification is available at /api/v1/automation/openapi.yaml. Tokens are shown once and should be kept in a secret store.'] },
		{ id:'admin-tools', title:'Host, logs and environment', summary:'Administrators: resources, per-bot usage, panel logs and editing variables.', body:['Administration → Host shows the machine and RivetPanel itself. Resources has live CPU, memory, load, disk and network figures with history charts from 1 hour to 30 days, the Docker runner, storage use and a list of things that need attention. Bots shows what each running bot uses against its limits. Panel logs follows the panel’s own log with level filter, search, copy and download; secrets are redacted and the view starts empty after a restart (the full log is in journalctl or docker logs).','Administration → Environment lists every RIVET_ variable with its default and where its value comes from, and edits most of them from the browser. Values are checked as a whole before they are stored and apply after a restart; the page shows what is waiting and offers Restart panel when systemd or a container restart policy will start RivetPanel again. Variables read before the database opens, and those that widen what the panel may do to the host, stay in the environment file. From the host, rivetpanel env lists the saved values and rivetpanel env reset drops them.','Press Ctrl+K anywhere to search pages, settings, environment variables, bots, sites, people, AI chats and actions; several words narrow the search and Tab switches scope.'] },
		{ id:'log-archive', title:'Log archive and retention', summary:'Daily log files, the archive job, downloads and how long graph data is kept.', body:['Console output of every bot and game server (local and on remote nodes) is copied every few minutes into one file per day, and the panel writes its own log the same way. A day starts at the archive time in the chosen time zone (default 00:00, server local time) and is named by the date it starts on. Shortly after it ends, the day file is compressed into a .log.gz archive; archives older than the retention (default 30 days) are deleted, then the oldest beyond the optional size limit.','Administration → Logs and retention sets the archive time, time zone, retention, size limit, copy interval and whether console output and the panel log are written, shows live and archived disk use and the last run, and has Run archival now. Holders of host monitoring (system.view) see the settings read-only. The same page sets how long graphs keep data: resource graphs (30-second samples, 7 days by default), analytics 5-minute, hourly and daily detail, and status page history (at least 90 days).','On a bot or game server, Console → Log history lists its days: download any archive, or view and download the current day. Panel log days are listed on the Logs and retention page. Build, deploy and backup output, add-on container logs and Docker’s own logs are not archived by day. The log folders are not part of rivetpanel backup; output that Docker drops before a copy (about 30 MB per container) is lost, so lower the copy interval for very chatty servers.'] },
		{ id:'operations', title:'Operations guide', summary:'Install, update, diagnose and recover.', body:['Deploy with the provided container or systemd units, configure the public URL, and verify /api/v1/healthz and /api/v1/readyz.','Workspace ownership: bots and game servers run as a non-root user that owns their files on the host. RIVET_CONTAINER_USER and RIVET_WORKSPACE_OWNER are used exactly as set. With neither set, a panel running as root or with CAP_CHOWN (the systemd unit) uses the unprivileged 65532:65532; a panel started as a normal user with RIVET_ENV=development uses its own uid:gid instead, logs a warning and shows an informational Workspace ownership check under Diagnostics. That fallback is meant for trying the panel out: containers then run with the same host uid that owns the database and keys, so in production the panel refuses to start that way unless RIVET_ALLOW_SHARED_UID=1 is set (then Diagnostics shows a warning). For production run the panel through the systemd unit or set both variables (always set them under rootless Docker or userns-remap). rivet-agent applies the same rule to its --user and --workspace-owner, with --allow-shared-uid (RIVET_AGENT_ALLOW_SHARED_UID=1) as its opt-in.','Before upgrades, take and verify a backup. Review release notes, apply the new binary or image, and confirm the schema migration and readiness checks.','For recovery, preserve the database, workspace directory and encryption keys together. Without matching key material, sealed secrets cannot be recovered.'] }
	];
	const filtered = $derived(sections.filter((s)=>(s.title+' '+s.summary+' '+s.body.join(' ')).toLowerCase().includes(query.trim().toLowerCase())));
	const iconFor = (id: string): IconName => ({ version:'commit', quickstart:'rocket', 'remote-nodes':'monitor', deploy:'github', publish:'upload', workspaces:'users', sites:'globe', ai:'bolt', appearance:'sun', widgets:'grid', 'widget-data':'code', telemetry:'activity', health:'shield', security:'key', backups:'archive', automation:'bolt', operations:'terminal' } as Record<string, IconName>)[id] ?? 'book';
</script>

